at::Tensor rmsprop_custom_impl_npu(const at::Tensor& param,
                                   const at::Tensor& grad,
                                   const at::Tensor& v,
                                   double lr,
                                   double alpha,
                                   double eps) {
    at::Tensor result = at::empty_like(param);
    EXEC_NPU_CMD(aclnnRmspropCustom, param, grad, v, static_cast<float>(lr),
                 static_cast<float>(alpha), static_cast<float>(eps), result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("rmsprop_custom", &rmsprop_custom_impl_npu);
}

